#!/usr/bin/env bash
# Cabeçalho portável que localiza o Bash através do PATH do sistema
echo "Script executado pelo interpretador correto: $BASH_VERSION"

while getopts ":e:p:h" opt; do
  case "$opt" in
    e) ENV="$OPTARG" ;;
    p) PORTA="$OPTARG" ;;
    h) echo "Uso: $0 -e <ambiente> -p <porta>"; exit 0 ;;
    \?) echo "Opção inválida: -$OPTARG" >&2; exit 1 ;;
    :) echo "A opção -$OPTARG requer um valor." >&2; exit 1 ;;
  esac
done
echo "Ambiente: ${ENV:-dev}, Porta: ${PORTA:-80}"

log_info() {
  echo "[$(date +'%Y-%m-%d %H:%M:%S')] [INFO]  $*"
}

log_error() {
  echo "[$(date +'%Y-%m-%d %H:%M:%S')] [ERROR] $*" >&2
}

log_info "Conectando ao cluster..."
log_error "Falha de autenticação no banco!"
